package android.graphics;import java.awt.*;public class Canvas {final Bitmap bitmap;public Canvas(Bitmap b){bitmap=b;}public void drawRect(float l,float t,float r,float b,Paint p){Graphics2D g=bitmap.pixels.createGraphics();g.setComposite(AlphaComposite.Clear);g.fillRect((int)l,(int)t,(int)(r-l),(int)(b-t));g.dispose();}public void drawBitmap(Bitmap b,float x,float y,Paint p){Graphics2D g=bitmap.pixels.createGraphics();g.setComposite(AlphaComposite.SrcOver);g.drawImage(b.pixels,(int)x,(int)y,null);g.dispose();}}